code.solution:
import math

def ticks_to_distance(ticks, ticks_per_rev, wheel_radius):
    return 2 * math.pi * wheel_radius * ticks / ticks_per_rev

def update_pose(x, y, theta, d_left, d_right, wheel_base):
    d = (d_left + d_right) / 2
    dtheta = (d_right - d_left) / wheel_base
    mid = theta + dtheta / 2
    return (x + d * math.cos(mid), y + d * math.sin(mid), theta + dtheta)

